/** @typedef {{version:3,clauses:readonly IndexedReviewAuditClause[],novelty:'new'|'duplicate',revisionReason:'none'|'source'|'image'|'duplicate'|'quality'}} IndexedReviewAudit */
/** @typedef {{claimEnd:number|'END',textEvidence:readonly {anchorIndex:number,start:number,end:number}[],pixelEvidence:readonly {imageId:string,cue:string}[],previousEvidence:readonly {priorId:string,start:number,end:number}[]}} ReviewAuditClause */
/** @typedef {{version:4,clauses:readonly ReviewAuditClause[],novelty:'new'|'duplicate',revisionReason:'none'|'source'|'image'|'duplicate'|'quality'}} OrderedEndReviewAudit */
/** @typedef {{textEvidence:readonly {anchorIndex:number,start:number,end:number}[],pixelEvidence:readonly {imageId:string,cue:string}[],previousEvidence:readonly {priorId:string,start:number,end:number}[]}} ReviewClauseEvidence */
/** @typedef {ReviewClauseEvidence & {claimEnd:number}} NonFinalReviewAuditClause */
/** @typedef {{version:5,clauses:readonly NonFinalReviewAuditClause[],finalClause:ReviewClauseEvidence|null,novelty:'new'|'duplicate',revisionReason:'none'|'source'|'image'|'duplicate'|'quality'}} ReviewAudit */
/** @typedef {ReviewClauseEvidence & {supportsWholeClaim:boolean}} WholeClaimReviewClauseEvidence */
/** @typedef {{version:8,clauses:readonly (WholeClaimReviewClauseEvidence & {claimEnd:number})[],finalClause:WholeClaimReviewClauseEvidence|null}} CriticAudit */
/** @typedef {{version:6|7,clauses:readonly NonFinalReviewAuditClause[],finalClause:ReviewClauseEvidence|null,novelty:'new'|'duplicate',revisionReason:'none'|'source'|'image'|'duplicate'|'quality'}} HistoricalDerivedReviewAudit */
